mapper.select:
SELECT fm.id, fm.data_set_id, ds.category_id, fm.original_name, fm.storage_name, fm.storage_key, fm.storage_type, fm.extension, fm.size_bytes, fm.sha256, fm.uploaded_by, fm.upload_status, fm.cleanup_status, fm.error_message, fm.create_time, fm.update_time, fm.deleted FROM ocean_gis.gis_file_meta fm LEFT JOIN ocean_gis.gis_data_set ds ON ds.id = fm.data_set_id WHERE fm.deleted = 1
AND fm.data_set_id = #{dataSetId}
AND ds.category_id = #{categoryId}
AND fm.original_name LIKE CONCAT('%', #{originalName}, '%')
AND fm.extension = #{extension}
AND fm.upload_status = #{uploadStatus}
ORDER BY fm.create_time DESC

mapper.update:
UPDATE ocean_gis.gis_file_meta
SET deleted = 0,
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 1

mapper.delete:
DELETE FROM ocean_gis.gis_file_meta
WHERE id = #{id}
  AND deleted = 1
